'use client'

import * as React from 'react'
import { Dialog } from '@base-ui/react/dialog'
import { Drawer } from '@base-ui/react/drawer'
import { IconX } from '@tabler/icons-react'

import { Button } from '@/components/ui/button'
import type { Promotion } from './promotion'
import { usePromotions } from './promotion-provider'
import { PromoGallery } from './promo-gallery'
import { PromoStory } from './promo-story'
import { PromoDialogContentView } from './promotion-views'

const WIDE = '(min-width: 768px)'

/** Re-renders on crossing the dialog/sheet breakpoint. */
function subscribeWide(onChange: () => void) {
  const list = window.matchMedia(WIDE)
  list.addEventListener('change', onChange)
  return () => list.removeEventListener('change', onChange)
}

/** True at `sm` and up, where the dialog layout is used; false on the server. */
function useWideScreen() {
  return React.useSyncExternalStore(
    subscribeWide,
    () => window.matchMedia(WIDE).matches,
    () => true,
  )
}

/** Title slot for the bottom-sheet layout, wired to the drawer for `aria-labelledby`. */
function SheetTitle(props: { className?: string; children?: React.ReactNode }) {
  return (
    <Drawer.Title
      {...props}
      className="text-foreground text-lg leading-snug font-medium text-balance"
    />
  )
}

/** Description slot for the bottom-sheet layout, wired for `aria-describedby`. */
function SheetDescription(props: {
  className?: string
  children?: React.ReactNode
}) {
  return (
    <Drawer.Description
      {...props}
      className="text-muted-foreground text-sm text-pretty"
    />
  )
}

/** Title slot for the centred and split layouts, wired to the dialog for `aria-labelledby`. */
function DialogTitle(props: {
  className?: string
  children?: React.ReactNode
}) {
  return (
    <Dialog.Title
      {...props}
      className="text-foreground text-lg leading-snug font-medium text-balance"
    />
  )
}

/** Description slot for the centred and split layouts, wired for `aria-describedby`. */
function DialogDescription(props: {
  className?: string
  children?: React.ReactNode
}) {
  return (
    <Dialog.Description
      {...props}
      className="text-muted-foreground text-sm text-pretty"
    />
  )
}

/**
 * A restrained modal for important, timed campaigns: a centred dialog on wide
 * screens and a bottom sheet on phones that can be swiped away. The provider
 * decides *whether* it may open (engagement, dismissal, once per visit, one
 * floating surface at a time).
 *
 * Closing by Not now, Escape, the backdrop or a swipe records a dismissal.
 * Following the button closes it too, but is reported as a click only, so
 * conversions are never counted as rejections.
 */
export function PromoDialog({
  layout = 'auto',
  container,
}: {
  /** `auto` picks the sheet below 768px. Force one for previews. */
  layout?: 'auto' | 'dialog' | 'sheet'
  /** Portal target, e.g. a device frame in a demo. Defaults to <body>. */
  container?: HTMLElement | null
}) {
  const {
    dialog,
    now,
    dismiss,
    complete,
    release,
    markShown,
    report,
    labels,
    Link,
  } = usePromotions()
  const wideScreen = useWideScreen()
  const wide = layout === 'auto' ? wideScreen : layout === 'dialog'
  // The last promotion shown stays mounted so the surface animates out with
  // its content instead of emptying first.
  const [shown, setShown] = React.useState<Promotion | null>(null)
  if (dialog && dialog.id !== shown?.id) setShown(dialog)
  const open = Boolean(dialog && shown && dialog.id === shown.id)

  React.useEffect(() => {
    // A modal is seen the moment it opens; it cannot be scrolled past.
    if (dialog) markShown(dialog)
  }, [dialog, markShown])

  if (!shown) return null

  const onOpenChange = (next: boolean) => {
    if (!next && open) dismiss(shown)
  }
  const content = (
    Title?: typeof SheetTitle,
    Description?: typeof SheetDescription,
    withoutMedia = false,
  ) => (
    <PromoDialogContentView
      promotion={
        withoutMedia
          ? { ...shown, media: undefined, gallery: undefined }
          : shown
      }
      now={now}
      Link={Link}
      onClick={() => {
        report('click', shown)
        complete(shown)
      }}
      onCopy={() => report('copy', shown)}
      onDismiss={() => dismiss(shown)}
      Title={Title}
      Description={Description}
    />
  )

  if (shown.presentation === 'story') {
    return (
      <PromoStory
        promotion={shown}
        open={open}
        onClose={() => release(shown)}
        onComplete={() => {
          report('click', shown)
          complete(shown)
        }}
        onCopy={() => report('copy', shown)}
        labels={labels}
        Link={Link}
        container={container}
      />
    )
  }

  const images = shown.gallery?.length
    ? shown.gallery
    : shown.media
      ? [shown.media]
      : []
  if (wide && shown.presentation === 'split' && images.length) {
    return (
      <Dialog.Root open={open} onOpenChange={onOpenChange}>
        <Dialog.Portal container={container}>
          <Dialog.Backdrop className="fixed inset-0 z-50 bg-black/25 transition-opacity duration-200 ease-out data-ending-style:opacity-0 data-ending-style:duration-150 data-starting-style:opacity-0 supports-backdrop-filter:backdrop-blur-[2px] dark:bg-black/55" />
          <Dialog.Popup
            data-slot="promo-dialog"
            data-presentation="split"
            className="bg-popover text-popover-foreground ring-foreground/10 fixed top-1/2 left-1/2 z-50 grid w-[calc(100%-2rem)] max-w-3xl -translate-x-1/2 -translate-y-1/2 grid-cols-[1.1fr_1fr] overflow-hidden rounded-[calc(var(--promo-radius,0.75rem)+0.5rem)] text-sm shadow-2xl ring-1 transition-[opacity,scale] duration-250 ease-[cubic-bezier(0.23,1,0.32,1)] outline-none data-ending-style:scale-[0.98] data-ending-style:opacity-0 data-ending-style:duration-150 data-starting-style:scale-[0.96] data-starting-style:opacity-0 motion-reduce:transition-opacity motion-reduce:data-ending-style:scale-100 motion-reduce:data-starting-style:scale-100"
          >
            <PromoGallery
              images={images}
              eager
              aspect="4 / 5"
              label={shown.title}
              className="h-full [&_img]:h-full"
            />
            <div className="flex flex-col justify-center p-7">
              {content(DialogTitle, DialogDescription, true)}
            </div>
            <Dialog.Close
              render={
                <Button
                  variant="ghost"
                  size="icon-sm"
                  className="bg-popover/80 absolute end-3 top-3 backdrop-blur-sm"
                />
              }
            >
              <IconX aria-hidden />
              <span className="sr-only">{labels.dismiss}</span>
            </Dialog.Close>
          </Dialog.Popup>
        </Dialog.Portal>
      </Dialog.Root>
    )
  }

  if (wide) {
    return (
      <Dialog.Root open={open} onOpenChange={onOpenChange}>
        <Dialog.Portal container={container}>
          <Dialog.Backdrop className="fixed inset-0 z-50 bg-black/20 transition-opacity duration-200 ease-out data-ending-style:opacity-0 data-ending-style:duration-150 data-starting-style:opacity-0 supports-backdrop-filter:backdrop-blur-[2px] dark:bg-black/50" />
          <Dialog.Popup
            data-slot="promo-dialog"
            className="bg-popover text-popover-foreground ring-foreground/10 fixed top-1/2 left-1/2 z-50 w-[calc(100%-2rem)] max-w-md -translate-x-1/2 -translate-y-1/2 rounded-2xl p-5 text-sm shadow-2xl ring-1 transition-[opacity,scale] duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] outline-none data-ending-style:scale-[0.97] data-ending-style:opacity-0 data-ending-style:duration-150 data-starting-style:scale-[0.96] data-starting-style:opacity-0 motion-reduce:transition-opacity motion-reduce:data-ending-style:scale-100 motion-reduce:data-starting-style:scale-100"
          >
            {content(DialogTitle, DialogDescription)}
            <Dialog.Close
              render={
                <Button
                  variant="ghost"
                  size="icon-sm"
                  className="bg-popover/80 absolute end-3 top-3 backdrop-blur-sm"
                />
              }
            >
              <IconX aria-hidden />
              <span className="sr-only">{labels.dismiss}</span>
            </Dialog.Close>
          </Dialog.Popup>
        </Dialog.Portal>
      </Dialog.Root>
    )
  }

  return (
    <Drawer.Root open={open} onOpenChange={onOpenChange}>
      <Drawer.Portal container={container}>
        <Drawer.Backdrop className="fixed inset-0 z-50 bg-black opacity-[calc(0.2*(1-var(--drawer-swipe-progress)))] transition-opacity duration-[450ms] ease-[cubic-bezier(0.32,0.72,0,1)] data-ending-style:opacity-0 data-ending-style:duration-[calc(var(--drawer-swipe-strength)*400ms)] data-starting-style:opacity-0 data-swiping:duration-0 dark:opacity-[calc(0.6*(1-var(--drawer-swipe-progress)))]" />
        <Drawer.Viewport className="fixed inset-0 z-50 flex items-end justify-center">
          <Drawer.Popup
            data-slot="promo-dialog"
            className="bg-popover text-popover-foreground ring-foreground/10 -mb-[3rem] max-h-[calc(85dvh+3rem)] w-full [transform:translateY(var(--drawer-swipe-movement-y))] overflow-y-auto overscroll-contain rounded-t-2xl px-4 pt-3 pb-[calc(1rem+env(safe-area-inset-bottom,0px)+3rem)] text-sm ring-1 transition-transform duration-[450ms] ease-[cubic-bezier(0.32,0.72,0,1)] outline-none data-ending-style:[transform:translateY(calc(100%-3rem+2px))] data-ending-style:duration-[calc(var(--drawer-swipe-strength)*400ms)] data-starting-style:[transform:translateY(calc(100%-3rem+2px))] data-swiping:select-none motion-reduce:transition-opacity motion-reduce:data-ending-style:opacity-0 motion-reduce:data-starting-style:opacity-0"
          >
            <div
              aria-hidden
              className="bg-muted-foreground/30 mx-auto mb-4 h-1 w-10 rounded-full"
            />
            <Drawer.Content className="mx-auto w-full max-w-lg">
              {content(SheetTitle, SheetDescription)}
            </Drawer.Content>
          </Drawer.Popup>
        </Drawer.Viewport>
      </Drawer.Portal>
    </Drawer.Root>
  )
}

'use client'

import * as React from 'react'
import { Dialog } from '@base-ui/react/dialog'
import { IconX } from '@tabler/icons-react'
import { useReducedMotion } from 'motion/react'
import { cn } from '@/lib/utils'

import { Button } from '@/components/ui/button'
import type { Promotion, PromotionMedia } from './promotion'
import type { PromotionLabels, PromotionLinkProps } from './promotion-provider'
import { PromoCode } from './promotion-views'

const SLIDE_MS = 6000

/**
 * A full-screen "what's new" story: slides with captions, segmented progress
 * at the top, tap the left third to go back and the rest to go on.
 *
 * It only ever opens because the visitor asked (the provider refuses to
 * auto-open a story), which is what earns it the whole screen. Slides move
 * on by themselves only while nobody is pressing, the tab is visible and
 * reduced motion is off; otherwise it is fully manual.
 */
export function PromoStory({
  promotion,
  open,
  onClose,
  onComplete,
  onCopy,
  labels,
  Link,
  container,
}: {
  promotion: Promotion
  open: boolean
  onClose: () => void
  onComplete: () => void
  onCopy: () => void
  labels: PromotionLabels
  Link: React.ComponentType<PromotionLinkProps>
  container?: HTMLElement | null
}) {
  const reduce = useReducedMotion()
  const slides: PromotionMedia[] = promotion.gallery?.length
    ? promotion.gallery
    : promotion.media
      ? [promotion.media]
      : []
  const [index, setIndex] = React.useState(0)
  const [held, setHeld] = React.useState(false)
  const [hidden, setHidden] = React.useState(false)
  const last = index >= slides.length - 1
  // The current segment's own CSS animation is the clock: pausing it pauses
  // the story, and its end moves to the next slide, so they never drift.
  const running = open && !reduce && slides.length > 1 && !last

  React.useEffect(() => {
    const onVisibility = () => setHidden(document.visibilityState === 'hidden')
    document.addEventListener('visibilitychange', onVisibility)
    return () => document.removeEventListener('visibilitychange', onVisibility)
  }, [])

  const go = (step: 1 | -1) =>
    setIndex((i) => Math.min(slides.length - 1, Math.max(0, i + step)))
  const slide = slides[index]

  return (
    <Dialog.Root
      open={open}
      onOpenChange={(next) => {
        if (!next) onClose()
      }}
    >
      <Dialog.Portal container={container}>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-black/85 transition-opacity duration-300 ease-out data-ending-style:opacity-0 data-ending-style:duration-200 data-starting-style:opacity-0 supports-backdrop-filter:backdrop-blur-md" />
        <Dialog.Popup
          data-slot="promo-story"
          onKeyDown={(event) => {
            if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') {
              const rtl =
                getComputedStyle(event.currentTarget).direction === 'rtl'
              go((event.key === 'ArrowRight') !== rtl ? 1 : -1)
            }
          }}
          className="fixed inset-0 z-50 m-auto flex h-full w-full flex-col overflow-hidden bg-black text-white transition-[opacity,scale] duration-300 ease-[cubic-bezier(0.23,1,0.32,1)] outline-none data-ending-style:scale-[0.98] data-ending-style:opacity-0 data-ending-style:duration-200 data-starting-style:scale-[0.96] data-starting-style:opacity-0 motion-reduce:transition-opacity sm:[aspect-ratio:9/16] sm:h-[min(52rem,calc(100%-2rem))] sm:w-auto sm:rounded-[calc(var(--promo-radius,0.75rem)+0.5rem)]"
        >
          {slide ? (
            // oxlint-disable-next-line nextjs/no-img-element
            <img
              key={slide.src + index}
              src={slide.src}
              alt={slide.alt}
              width={slide.width}
              height={slide.height}
              decoding="async"
              className="animate-in fade-in-0 absolute inset-0 size-full object-cover duration-300 motion-reduce:animate-none"
            />
          ) : null}
          <div
            aria-hidden
            className="pointer-events-none absolute inset-0 bg-[linear-gradient(to_bottom,rgb(0_0_0/0.55),transparent_22%,transparent_50%,rgb(0_0_0/0.8))]"
          />

          {/* Segmented progress: done, current (filling), to come. */}
          <div className="relative flex gap-1 px-3 pt-[max(0.75rem,env(safe-area-inset-top))]">
            {slides.map((s, i) => (
              <span
                key={s.src + i}
                className="h-0.5 flex-1 overflow-hidden rounded-full bg-white/30"
              >
                <span
                  key={i === index ? `run-${index}` : undefined}
                  onAnimationEnd={i === index ? () => go(1) : undefined}
                  className={cn(
                    'block h-full origin-left rounded-full bg-white rtl:origin-right',
                    i < index && 'scale-x-100',
                    i > index && 'scale-x-0',
                    i === index && !running && 'scale-x-100',
                  )}
                  style={
                    i === index && running
                      ? {
                          animation: `promo-story-fill ${SLIDE_MS}ms linear forwards`,
                          animationPlayState:
                            held || hidden ? 'paused' : 'running',
                        }
                      : undefined
                  }
                />
              </span>
            ))}
          </div>
          <style>{`@keyframes promo-story-fill{from{transform:scaleX(0)}to{transform:scaleX(1)}}`}</style>

          <div className="relative flex items-center gap-2 px-4 pt-3">
            {promotion.eyebrow ? (
              <span className="text-xs font-medium text-white/85">
                {promotion.eyebrow}
              </span>
            ) : null}
            <Dialog.Close
              render={
                <Button
                  variant="ghost"
                  size="icon-sm"
                  className="ms-auto text-white hover:bg-white/15 hover:text-white"
                />
              }
            >
              <IconX aria-hidden />
              <span className="sr-only">{labels.dismiss}</span>
            </Dialog.Close>
          </div>

          {/* Tap zones: back on the first third, on everywhere else. Holding pauses. */}
          <div
            className="relative flex-1"
            onPointerDown={() => setHeld(true)}
            onPointerUp={() => setHeld(false)}
            onPointerLeave={() => setHeld(false)}
          >
            <button
              type="button"
              aria-label={labels.previous}
              disabled={index === 0}
              onClick={() => go(-1)}
              className="absolute inset-y-0 start-0 w-1/3 outline-none focus-visible:bg-white/5"
            />
            <button
              type="button"
              aria-label={labels.next}
              disabled={last}
              onClick={() => go(1)}
              className="absolute inset-y-0 end-0 w-2/3 outline-none focus-visible:bg-white/5"
            />
          </div>

          <div className="relative flex flex-col gap-2 px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))]">
            {slide?.caption ? (
              <p
                key={index}
                aria-live="polite"
                className="animate-in fade-in-0 slide-in-from-bottom-1 text-sm text-white/85 duration-300 motion-reduce:animate-none"
              >
                {slide.caption}
              </p>
            ) : null}
            <Dialog.Title className="[font-family:var(--promo-display,inherit)] text-2xl leading-tight font-medium text-balance">
              {promotion.title}
            </Dialog.Title>
            {promotion.body ? (
              <Dialog.Description className="text-sm text-pretty text-white/80">
                {promotion.body}
              </Dialog.Description>
            ) : null}
            {promotion.code ? (
              <PromoCode
                code={promotion.code}
                reveal={promotion.revealCode}
                onCopy={onCopy}
                className="mt-1 self-start text-white"
              />
            ) : null}
            {promotion.cta ? (
              <Button
                size="lg"
                nativeButton={false}
                className="mt-2 bg-white text-black hover:bg-white/90"
                render={
                  <Link
                    href={promotion.cta.href}
                    onClick={onComplete}
                    {...(promotion.cta.external
                      ? { target: '_blank', rel: 'noopener noreferrer' }
                      : {})}
                  >
                    {promotion.cta.label}
                  </Link>
                }
              />
            ) : null}
          </div>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  )
}
